-- قاعدة بيانات مستقلة لقائمة المطعم. شغّل مرة واحدة في Supabase SQL Editor.
create table if not exists public.restaurant_admins (user_id uuid primary key references auth.users(id) on delete cascade);
create table if not exists public.restaurant_categories (id text primary key,name text not null,short text not null default '',image_url text,sort_order integer not null default 0,is_active boolean not null default true);
create table if not exists public.restaurant_menu_items (id text primary key,category_id text not null references public.restaurant_categories(id) on delete cascade,name text not null,image_url text,price numeric(12,0) not null default 0,serving_size text not null default '',ingredients text not null default '',preparation_time text not null default '',description text not null default '',sort_order integer not null default 0,is_active boolean not null default true);
create table if not exists public.restaurant_item_options (id bigint generated by default as identity primary key,item_id text not null references public.restaurant_menu_items(id) on delete cascade,name text not null,is_available boolean not null default true,sort_order integer not null default 0,unique(item_id,name));
create table if not exists public.restaurant_orders (id bigint generated by default as identity primary key,order_number text not null unique,tracking_token text,phone text not null,address text not null default '',items jsonb not null default '[]'::jsonb,subtotal numeric(12,0) not null default 0,delivery numeric(12,0) not null default 0,total numeric(12,0) not null default 0,status text not null default 'pending' check(status in ('pending','approved','rejected')),created_at timestamptz not null default now());
insert into public.restaurant_categories(id,name,short,sort_order) values ('main-dishes','الأطباق الرئيسية','🍛',0),('appetizers','المقبلات','🥗',1),('desserts','الحلويات','🍰',2),('drinks','المشروبات','🥤',3) on conflict(id) do nothing;

-- Migration safety if an earlier draft of these restaurant tables was already created.
alter table public.restaurant_orders add column if not exists tracking_token text;
update public.restaurant_orders set tracking_token = substr(md5(random()::text || clock_timestamp()::text),1,24) || substr(md5(random()::text || clock_timestamp()::text),1,24) where tracking_token is null;
alter table public.restaurant_orders alter column tracking_token set not null;
create unique index if not exists restaurant_orders_tracking_token_uidx on public.restaurant_orders(tracking_token);
do $$ begin
  if not exists (select 1 from pg_constraint where conname='restaurant_orders_tracking_token_format') then
    alter table public.restaurant_orders add constraint restaurant_orders_tracking_token_format check (tracking_token ~ '^[a-f0-9]{48}$');
  end if;
end $$;
drop function if exists public.get_restaurant_customer_orders(text);
create or replace function public.is_restaurant_admin() returns boolean language sql stable security definer set search_path=public as $$ select exists(select 1 from public.restaurant_admins where user_id=auth.uid()); $$;
grant execute on function public.is_restaurant_admin() to anon,authenticated;
alter table public.restaurant_admins enable row level security;
alter table public.restaurant_categories enable row level security;
alter table public.restaurant_menu_items enable row level security;
alter table public.restaurant_item_options enable row level security;
alter table public.restaurant_orders enable row level security;
drop policy if exists restaurant_categories_public_read on public.restaurant_categories;
drop policy if exists restaurant_menu_public_read on public.restaurant_menu_items;
drop policy if exists restaurant_options_public_read on public.restaurant_item_options;
drop policy if exists restaurant_orders_admin_update_pending on public.restaurant_orders;
drop policy if exists restaurant_admin_self_read on public.restaurant_admins; create policy restaurant_admin_self_read on public.restaurant_admins for select to authenticated using(user_id=auth.uid());
drop policy if exists restaurant_categories_read on public.restaurant_categories; create policy restaurant_categories_read on public.restaurant_categories for select to anon,authenticated using(is_active or public.is_restaurant_admin());
drop policy if exists restaurant_categories_admin_write on public.restaurant_categories; create policy restaurant_categories_admin_write on public.restaurant_categories for all to authenticated using(public.is_restaurant_admin()) with check(public.is_restaurant_admin());
drop policy if exists restaurant_menu_read on public.restaurant_menu_items; create policy restaurant_menu_read on public.restaurant_menu_items for select to anon,authenticated using(is_active or public.is_restaurant_admin());
drop policy if exists restaurant_menu_admin_write on public.restaurant_menu_items; create policy restaurant_menu_admin_write on public.restaurant_menu_items for all to authenticated using(public.is_restaurant_admin()) with check(public.is_restaurant_admin());
drop policy if exists restaurant_options_read on public.restaurant_item_options; create policy restaurant_options_read on public.restaurant_item_options for select to anon,authenticated using(is_available or public.is_restaurant_admin());
drop policy if exists restaurant_options_admin_write on public.restaurant_item_options; create policy restaurant_options_admin_write on public.restaurant_item_options for all to authenticated using(public.is_restaurant_admin()) with check(public.is_restaurant_admin());
drop policy if exists restaurant_orders_public_insert on public.restaurant_orders; create policy restaurant_orders_public_insert on public.restaurant_orders for insert to anon,authenticated with check(status='pending' and tracking_token ~ '^[a-f0-9]{48}$');
drop policy if exists restaurant_orders_admin_read on public.restaurant_orders; create policy restaurant_orders_admin_read on public.restaurant_orders for select to authenticated using(public.is_restaurant_admin());
drop policy if exists restaurant_orders_admin_update on public.restaurant_orders; create policy restaurant_orders_admin_update on public.restaurant_orders for update to authenticated using(public.is_restaurant_admin() and status='pending') with check(public.is_restaurant_admin() and status in ('approved','rejected'));
grant select on public.restaurant_categories,public.restaurant_menu_items,public.restaurant_item_options to anon,authenticated;
grant insert,update,delete on public.restaurant_categories,public.restaurant_menu_items,public.restaurant_item_options to authenticated;
grant select on public.restaurant_admins to authenticated;
grant insert on public.restaurant_orders to anon,authenticated;
grant select,update on public.restaurant_orders to authenticated;
grant usage,select on sequence public.restaurant_item_options_id_seq to authenticated;
create or replace function public.get_restaurant_customer_orders(p_phone text,p_tracking_token text) returns setof public.restaurant_orders language sql security definer set search_path=public as $$ select * from public.restaurant_orders where phone=p_phone and tracking_token=p_tracking_token order by created_at desc limit 10; $$;
grant execute on function public.get_restaurant_customer_orders(text,text) to anon,authenticated;
insert into storage.buckets(id,name,public) values('restaurant-menu-images','restaurant-menu-images',true) on conflict(id) do nothing;
drop policy if exists restaurant_images_public_read on storage.objects; create policy restaurant_images_public_read on storage.objects for select to anon,authenticated using(bucket_id='restaurant-menu-images');
drop policy if exists restaurant_images_admin_insert on storage.objects; create policy restaurant_images_admin_insert on storage.objects for insert to authenticated with check(bucket_id='restaurant-menu-images' and public.is_restaurant_admin());
drop policy if exists restaurant_images_admin_update on storage.objects; create policy restaurant_images_admin_update on storage.objects for update to authenticated using(bucket_id='restaurant-menu-images' and public.is_restaurant_admin()) with check(bucket_id='restaurant-menu-images' and public.is_restaurant_admin());
